const PANEL_RULES = [
  {
    panel: 'route-map',
    keywords: ['rute', 'kapal', 'pelabuhan', 'cargo', 'shipping', 'freight'],
  },
  {
    panel: 'tariff',
    keywords: ['tarif', 'bea masuk', 'hs code', 'pajak', 'duty'],
  },
  {
    panel: 'compliance',
    keywords: ['syarat', 'dokumen', 'izin', 'bpom', 'karantina', 'ska'],
  },
  {
    panel: 'market',
    keywords: ['pasar', 'buyer', 'peluang', 'harga'],
  },
];

function normalizePayload(json) {
  if (json.body && typeof json.body === 'object' && !Array.isArray(json.body)) {
    return json.body;
  }

  if (typeof json.body === 'string') {
    try {
      return JSON.parse(json.body);
    } catch {
      return { text: json.body };
    }
  }

  return json;
}

function classify(payload) {
  const text = [
    payload.text,
    payload.message,
    payload.query,
    payload.prompt,
    payload.topic,
    payload.description,
    payload.panel,
    payload.data,
  ]
    .map((value) => {
      if (value == null) return '';
      return typeof value === 'string' ? value : JSON.stringify(value);
    })
    .join(' ')
    .toLowerCase();

  const matchedRule = PANEL_RULES.find((rule) =>
    rule.keywords.some((keyword) => text.includes(keyword)),
  );

  return matchedRule ? matchedRule.panel : 'route-map';
}

return items.map((item) => {
  const payload = normalizePayload(item.json);
  const query = item.json.query && typeof item.json.query === 'object' ? item.json.query : {};
  const sessionId = payload.sessionId ?? payload.session_id ?? query.sessionId ?? query.session_id ?? '';

  return {
    json: {
      sessionId,
      panel: classify(payload),
      data: payload.data ?? payload,
    },
  };
});
